"""Generate docs/cli/reference.md from the argparse parser, so the flag reference can't drift.

    python -m sample_shepherd.cli_reference > docs/cli/reference.md

It walks the parser's actions rather than printing --help, because help formatting changes
between Python versions and the test compares the output byte for byte.
"""
from __future__ import annotations

import argparse

from sample_shepherd.cli import build_parser

HEADER = """\
# Command reference

<!-- Generated by `python -m sample_shepherd.cli_reference > docs/cli/reference.md`.
     Don't edit by hand: tests/test_cli_reference.py fails when this is out of date. -->

Every command and flag, generated from the code. For what each command is for and how it
keeps you safe, see [commands.md](commands.md). `sample-shepherd <command> --help` prints
the same information.

"""


def _subcommands(p: argparse.ArgumentParser):
    """(name, help, parser) for each subcommand, in definition order."""
    for act in p._actions:
        if isinstance(act, argparse._SubParsersAction):
            helps = {c.dest: c.help for c in act._choices_actions}
            for name, sub in act.choices.items():
                yield name, helps.get(name) or sub.description or "", sub


def _flag(act: argparse.Action) -> str:
    if not act.option_strings:
        name = act.metavar or act.dest
        return f"`{name} ...`" if act.nargs in ("*", "+") else f"`{name}`"
    names = ", ".join(act.option_strings)
    if act.nargs == 0:
        return f"`{names}`"
    meta = act.metavar or act.dest.upper()
    if act.nargs in ("*", "+"):
        meta += " ..."
    return f"`{names} {meta}`"


def _row(act: argparse.Action) -> str:
    notes = []
    if act.required and act.option_strings:
        notes.append("required")
    if act.option_strings and act.nargs != 0 and act.default not in (None, argparse.SUPPRESS) \
            and "default" not in (act.help or ""):
        notes.append(f"default `{act.default}`")
    help = (act.help or "").replace("|", "\\|").replace("<", "&lt;").replace(">", "&gt;")
    if notes:
        help = f"{help} ({', '.join(notes)})" if help else ", ".join(notes)
    return f"| {_flag(act)} | {help} |"


def _table(p: argparse.ArgumentParser, skip=("help",)) -> list[str]:
    acts = [a for a in p._actions
            if a.dest not in skip and not isinstance(a, (argparse._SubParsersAction, argparse._HelpAction))]
    if not acts:
        return ["No options."]
    return ["| Argument | Description |", "|---|---|", *map(_row, acts)]


def _walk(p: argparse.ArgumentParser, path: list[str], out: list[str]) -> None:
    for name, help, sub in _subcommands(p):
        full = [*path, name]
        if any(True for _ in _subcommands(sub)):
            out += [f"## `{' '.join(full)}`", "", f"{help[0].upper()}{help[1:]}.", ""]
            _walk(sub, full, out)
        else:
            level = "###" if path else "##"
            out += [f"{level} `{' '.join(full)}`", "", f"{help[0].upper()}{help[1:]}.", "",
                    *_table(sub), ""]


def render() -> str:
    ap = build_parser()
    out = [HEADER.rstrip("\n"), "", "## Global options", "",
           "These go before the command: `sample-shepherd --device 2 device info`.", "",
           *_table(ap, skip=("help", "version")), ""]
    _walk(ap, [], out)
    return "\n".join(out).rstrip("\n") + "\n"


if __name__ == "__main__":
    print(render(), end="")
